"""
    this function will convert bytes to MB.... GB... etc

    reference: http://stackoverflow.com/questions/2104080/how-to-check-file-size-in-python
    """
def convert_bytes(num: Any) -> object {
    for x in ['bytes', 'KB', 'MB', 'GB', 'TB'] {
        if (num < 1024.0) {
            return ("%3.1f %s" % (num, x));
        }
        num /= 1024.0;
    }
}

